<?php
namespace Tests;
use App\Services\{SalonStore,Tenant};
use Illuminate\Support\Facades\{Artisan,DB,Crypt,Http};
use Illuminate\Support\Str;
class HistoryPaginationTest extends \Illuminate\Foundation\Testing\TestCase
{
 public function createApplication(){$app=require __DIR__.'/../bootstrap/app.php';$app->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $app;}
 protected function setUp():void{parent::setUp();Artisan::call('migrate',['--force'=>true]);$s=SalonStore::initial();$s['subscription']=['plan'=>'pro','status'=>'active'];$s['clients']=[['id'=>'own','name'=>'Own','guestId'=>10,'email'=>'guest@example.com','phone'=>'']];$s['settings']['loyaltyEnabled']=true;$s['loyalty']=['ledger'=>array_map(fn($n)=>['id'=>(string)$n,'clientId'=>'own','bookingId'=>(string)$n,'delta'=>1,'type'=>'earn','at'=>'2036-01-01T00:00:00Z'],range(1,65))];DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode($s)]);$this->withSession(['admin'=>true,'provider_id'=>1]);Http::preventStrayRequests();}
 public function test_campaign_history_accesses_old_records_past_100_and_single_campaign_fetch_is_scoped():void{
  $ids=[];for($i=0;$i<121;$i++){$ids[]=$id=(string)Str::uuid();DB::table('marketing_campaigns')->insert(['id'=>$id,'provider_id'=>1,'engine'=>'mailchimp','subject'=>'Campaign '.$i,'html'=>'x','status'=>'draft','created_at'=>now()->subSeconds($i),'updated_at'=>now()]);}DB::table('marketing_campaigns')->insert(['id'=>(string)Str::uuid(),'provider_id'=>2,'engine'=>'mailchimp','subject'=>'Other','html'=>'x','status'=>'draft','created_at'=>now()->addHour(),'updated_at'=>now()]);
  $this->getJson('/api/marketing/campaigns?page=21&perPage=10000')->assertOk()->assertJsonCount(5,'campaigns')->assertJsonPath('campaignPagination.total',121)->assertJsonPath('campaigns.0.subject','Campaign 100');$this->getJson('/api/marketing/campaigns?campaignId='.$ids[120])->assertJsonCount(1,'campaigns')->assertJsonPath('campaigns.0.subject','Campaign 120');$this->getJson('/api/marketing/campaigns?page=999')->assertJsonPath('campaignPagination.page',25)->assertJsonCount(1,'campaigns');$this->getJson('/api/marketing/campaigns?page=0')->assertUnprocessable();
 }
 public function test_waitlist_history_reaches_beyond_200_with_fixed_10_rows_and_no_other_provider():void{
  $payload=Crypt::encryptString(json_encode(['name'=>'Guest','email'=>'g@example.com','services'=>['cut'],'timeFrom'=>'08:00','timeTo'=>'20:00']));for($i=0;$i<211;$i++)DB::table('waitlist_entries')->insert(['id'=>(string)Str::uuid(),'provider_id'=>1,'dedup'=>hash('sha256',(string)$i),'token_hash'=>hash('sha256','token'.$i),'payload'=>$payload,'status'=>'active','first_date'=>'2036-01-01','last_date'=>'2036-01-02','created_at'=>now()->subSeconds($i),'updated_at'=>now()]);$this->getJson('/api/waitlist?page=21')->assertOk()->assertJsonCount(10,'items')->assertJsonPath('pagination.total',211);$this->getJson('/api/waitlist?page=22')->assertJsonCount(1,'items');$this->withSession(['admin'=>false]);$this->getJson('/api/waitlist?page=1')->assertForbidden();
 }
 public function test_delivery_filter_runs_before_paging_and_does_not_return_encrypted_payload():void{
  for($i=0;$i<130;$i++)DB::table('deliveries')->insert(['provider_id'=>1,'dedup'=>hash('sha256','own'.$i),'payload'=>Crypt::encryptString(json_encode(['event'=>'created','recipient'=>'guest@example.com'])),'status'=>$i<101?'sent':'failed','available_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('deliveries')->insert(['provider_id'=>2,'dedup'=>hash('sha256','other'),'payload'=>'private','status'=>'failed','available_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);
  $this->getJson('/api/deliveries?page=6')->assertOk()->assertJsonCount(20,'items')->assertJsonPath('pagination.total',130)->assertJsonMissingPath('items.0.payload');$this->getJson('/api/deliveries?page=2&scope=errors')->assertJsonCount(9,'items')->assertJsonPath('pagination.total',29)->assertJsonPath('counts.all',130)->assertJsonPath('counts.errors',29);$this->getJson('/api/deliveries?page=1&scope=invalid')->assertUnprocessable();
 }
 public function test_sms_history_has_independent_pages_and_owner_scope_without_payment_secrets():void{
  for($i=0;$i<115;$i++)DB::table('sms_ledger')->insert(['provider_id'=>1,'reference'=>'own-'.$i,'kind'=>'topup','amount'=>100,'details'=>'secret','created_at'=>now(),'updated_at'=>now()]);DB::table('sms_ledger')->insert(['provider_id'=>2,'reference'=>'other','kind'=>'topup','amount'=>999,'created_at'=>now(),'updated_at'=>now()]);
  for($i=0;$i<55;$i++)DB::table('sms_topups')->insert(['id'=>(string)Str::uuid(),'provider_id'=>1,'request_id'=>(string)Str::uuid(),'amount'=>3000,'status'=>'paid','checkout_url'=>'https://secret.example','created_at'=>now(),'updated_at'=>now()]);
  $this->getJson('/api/sms-wallet/history/ledger?page=11')->assertOk()->assertJsonCount(10,'items')->assertJsonPath('pagination.total',115)->assertJsonMissingPath('items.0.details');$this->getJson('/api/sms-wallet/history/topups?page=6')->assertJsonCount(5,'items')->assertJsonMissingPath('items.0.checkout_url');$this->withSession(['admin'=>false]);$this->getJson('/api/sms-wallet/history/ledger?page=1')->assertForbidden();
 }
 public function test_loyalty_history_keeps_balance_and_pages_all_movements_past_50():void{
  $this->getJson('/api/clients/own/loyalty?page=6')->assertOk()->assertJsonPath('balance',65)->assertJsonCount(10,'history')->assertJsonPath('history.0.id','15')->assertJsonPath('historyPagination.total',65);$this->getJson('/api/clients/own/loyalty?page=7')->assertJsonCount(5,'history');DB::table('guest_accounts')->insert(['id'=>10,'provider'=>'email','subject'=>'ten','email'=>'guest@example.com','name'=>'Guest','email_verified'=>true,'created_at'=>now(),'updated_at'=>now()]);$this->withSession(['admin'=>false,'guest_id'=>10]);$this->getJson('/api/guest/loyalty?page=7')->assertOk()->assertJsonCount(5,'history')->assertJsonPath('balance',65);$this->getJson('/api/clients/own/loyalty?page=1')->assertForbidden();
 }
}
